import math

def layer_norm_rows(rows, eps=1e-5):
    result = []
    for row in rows:
        if not row:
            raise ValueError("不能归一化空行")
        mean = sum(row) / len(row)
        var = sum((value - mean) ** 2 for value in row) / len(row)
        scale = math.sqrt(var + eps)
        result.append([(value - mean) / scale for value in row])
    return result

