import torch

def last_dim_norm(x, gamma, beta, eps=1e-5):
    mean = x.mean(dim=-1, keepdim=True)
    var = x.var(dim=-1, keepdim=True, unbiased=False)
    normalized = (x - mean) * torch.rsqrt(var + eps)
    return normalized * gamma + beta

