def prefix_allowed(prefix_len, action_len):
    if prefix_len < 0 or action_len < 0:
        raise ValueError("长度不能为负")
    total = prefix_len + action_len
    result = []
    for query in range(total):
        row = []
        for key in range(total):
            if query < prefix_len:
                row.append(key < prefix_len)
            else:
                row.append(key < prefix_len or key <= query)
        result.append(row)
    return result

