import torch
from torch import nn

class PracticeBlock(nn.Module):
    def __init__(self, dim=8):
        super().__init__()
        self.n1, self.n2 = nn.LayerNorm(dim), nn.LayerNorm(dim)
        self.attn = nn.MultiheadAttention(dim, 2, dropout=0, batch_first=True)
        self.ffn = nn.Sequential(nn.Linear(dim, 16), nn.GELU(), nn.Linear(16, dim))

    def forward(self, x, blocked):
        z = self.n1(x)
        update, _ = self.attn(z, z, z, attn_mask=blocked, need_weights=False)
        h = x + update
        return h + self.ffn(self.n2(h))

