import torch

def rope_pairs(x, positions, base=10000.0):
    dim = x.shape[-1]
    if dim % 2:
        raise ValueError("D 必须为偶数")
    freq = base ** (-torch.arange(0, dim, 2, device=x.device, dtype=x.dtype) / dim)
    angle = positions.to(x)[:, None] * freq[None, :]
    c, s = angle.cos()[None], angle.sin()[None]
    a, b = x[..., 0::2], x[..., 1::2]
    return torch.stack((a*c-b*s, a*s+b*c), dim=-1).flatten(-2)

