import torch

def masked_pool(tokens, valid):
    if tokens.ndim != 3 or valid.shape != tokens.shape[:2] or valid.dtype != torch.bool:
        raise ValueError('expected [B,N,D] and boolean [B,N]')
    counts = valid.sum(dim=1, keepdim=True)
    if bool((counts == 0).any()):
        raise ValueError('every sample needs a valid token')
    if not bool(torch.isfinite(tokens[valid]).all()):
        raise ValueError('nonfinite valid token')
    safe = torch.where(valid.unsqueeze(-1), tokens, torch.zeros_like(tokens))
    return safe.sum(dim=1) / counts.to(tokens.dtype)

